## t004: fix: set status code before publishing diagnostics error channel

## Summary

Fixes #6409

Previously, the `tracing:fastify.request.handler:error` diagnostics channel would always report `reply.statusCode` as 200 because the channel was published before the error handler had a chance to set the appropriate status code.

This fix sets the status code based on the error's `statusCode` or `status` property before publishing the diagnostics channel event, so subscribers can see the correct status code.

## Changes

- `lib/handle-request.js`: Set status code before publishing error channel (both sync error paths)
- `lib/wrap-thenable.js`: Set status code before publishing error channel (async error path)
- Added tests verifying the fix

## Test plan

- [x] Added test: `diagnostics channel error event should report correct status code` - verifies error with statusCode
- [x] Added test: `diagnostics channel error event should report 500 for errors without status` - verifies plain errors default to 500
- [x] Added test: `diagnostics channel error event should report correct status with custom error handler` - documents behavior with custom error handlers
- [x] All existing tests pass

You may update existing tests whose expectations your change intentionally alters.

Acceptance tests:

`test/diagnostics-channel/error-status.pr6412.test.js`

```js
'use strict'

const { test } = require('node:test')
const Fastify = require('../..')
const statusCodes = require('node:http').STATUS_CODES
const diagnostics = require('node:diagnostics_channel')

test('diagnostics channel error event should report correct status code', async (t) => {
  t.plan(3)
  const fastify = Fastify()
  t.after(() => fastify.close())

  let diagnosticsStatusCode

  const channel = diagnostics.channel('tracing:fastify.request.handler:error')
  const handler = (msg) => {
    diagnosticsStatusCode = msg.reply.statusCode
  }
  channel.subscribe(handler)
  t.after(() => channel.unsubscribe(handler))

  fastify.get('/', async () => {
    const err = new Error('test error')
    err.statusCode = 503
    throw err
  })

  const res = await fastify.inject('/')

  t.assert.strictEqual(res.statusCode, 503)
  t.assert.strictEqual(diagnosticsStatusCode, 503, 'diagnostics channel should report correct status code')
  t.assert.strictEqual(diagnosticsStatusCode, res.statusCode, 'diagnostics status should match response status')
})

test('diagnostics channel error event should report 500 for errors without status', async (t) => {
  t.plan(3)
  const fastify = Fastify()
  t.after(() => fastify.close())

  let diagnosticsStatusCode

  const channel = diagnostics.channel('tracing:fastify.request.handler:error')
  const handler = (msg) => {
    diagnosticsStatusCode = msg.reply.statusCode
  }
  channel.subscribe(handler)
  t.after(() => channel.unsubscribe(handler))

  fastify.get('/', async () => {
    throw new Error('plain error without status')
  })

  const res = await fastify.inject('/')

  t.assert.strictEqual(res.statusCode, 500)
  t.assert.strictEqual(diagnosticsStatusCode, 500, 'diagnostics channel should report 500 for plain errors')
  t.assert.strictEqual(diagnosticsStatusCode, res.statusCode, 'diagnostics status should match response status')
})

test('diagnostics channel error event should report correct status with custom error handler', async (t) => {
  t.plan(3)
  const fastify = Fastify()
  t.after(() => fastify.close())

  let diagnosticsStatusCode

  const channel = diagnostics.channel('tracing:fastify.request.handler:error')
  const handler = (msg) => {
    diagnosticsStatusCode = msg.reply.statusCode
  }
  channel.subscribe(handler)
  t.after(() => channel.unsubscribe(handler))

  fastify.setErrorHandler((error, request, reply) => {
    reply.status(503).send({ error: error.message })
  })

  fastify.get('/', async () => {
    throw new Error('handler error')
  })

  const res = await fastify.inject('/')

  // Note: The diagnostics channel fires before the custom error handler runs,
  // so it reports 500 (default) rather than 503 (set by custom handler).
  // This is expected behavior - the error channel reports the initial error state.
  t.assert.strictEqual(res.statusCode, 503)
  t.assert.strictEqual(diagnosticsStatusCode, 500, 'diagnostics channel reports status before custom handler')
  t.assert.notStrictEqual(diagnosticsStatusCode, res.statusCode, 'custom handler can change status after diagnostics')
})
```

## t005: fix(ts): Align routerOptions defaultRoute types with runtime

## Summary

Fixes #6389.

### What was broken

`routerOptions.defaultRoute` and `routerOptions.onBadUrl` were typed as receiving `FastifyReply`, but the runtime always provides the raw Node `ServerResponse`. Consumers relying on the typed `FastifyReply` helpers (for example `reply.send`) hit runtime errors despite the compiler reporting everything as safe.

### What this PR changes

- retunes the TypeScript definitions for both callbacks to `RawRequestDefaultExpression`/`RawReplyDefaultExpression`, so the compiler finally describes what the runtime actually hands you
- calls out in `docs/Reference/Server.md` that these hooks get raw `IncomingMessage`/`ServerResponse` objects, setting expectations for folks writing plain JavaScript too
- drops a tsd regression in `test/types/instance.test-d.ts` so `routerOptions` can’t quietly drift back to exposing `FastifyReply`

### Testing evidence

- `npm run lint` → passes (eslint only)
- `npm run unit` → passes (borp, 2,140 tests run, 0 failures, 4 skips)
- `npm run test:typescript` → passes (tsc + tsd)
- `npm run benchmark --if-present` → passes (autocannon ~119k req/s avg, 672 MB read over 30 s)

You may update existing tests whose expectations your change intentionally alters.

Acceptance tests:

`test/issue-4959.pr6392.test.js`

```js
'use strict'

const { test } = require('node:test')
const http = require('node:http')
const Fastify = require('../fastify')
const { setTimeout } = require('node:timers')

/*
* Ensure that a socket error during the request does not cause the
* onSend hook to be called multiple times.
*
* @see https://github.com/fastify/fastify/issues/4959
*/
function runBadClientCall (reqOptions, payload, waitBeforeDestroy) {
  let innerResolve, innerReject
  const promise = new Promise((resolve, reject) => {
    innerResolve = resolve
    innerReject = reject
  })

  const postData = JSON.stringify(payload)

  const req = http.request({
    ...reqOptions,
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  }, () => {
    innerReject(new Error('Request should have failed'))
  })

  // Kill the socket after the request has been fully written.
  // Destroying it on `connect` can race before any bytes are sent, making the
  // server-side assertions (hooks/handler) non-deterministic.
  //
  // To keep the test deterministic, we optionally wait for a server-side signal
  // (e.g. onSend entered) before aborting the client.
  let socket
  req.on('socket', (s) => { socket = s })
  req.on('finish', () => {
    if (waitBeforeDestroy && typeof waitBeforeDestroy.then === 'function') {
      Promise.race([
        waitBeforeDestroy,
        new Promise(resolve => setTimeout(resolve, 200))
      ]).then(() => {
        if (socket) socket.destroy()
      }, innerResolve)
      return
    }
    setTimeout(() => { socket.destroy() }, 0)
  })
  req.on('error', innerResolve)
  req.write(postData)
  req.end()

  return promise
}

test('should handle a socket error', async (t) => {
  t.plan(4)
  const fastify = Fastify()

  let resolveOnSendEntered
  const onSendEntered = new Promise((resolve) => {
    resolveOnSendEntered = resolve
  })

  function shouldNotHappen () {
    t.assert.fail('This should not happen')
  }
  process.on('unhandledRejection', shouldNotHappen)

  t.after(() => {
    fastify.close()
    process.removeListener('unhandledRejection', shouldNotHappen)
  })

  fastify.addHook('onRequest', async (request, reply) => {
    t.assert.ok('onRequest hook called')
  })

  fastify.addHook('onSend', async (request, reply, payload) => {
    if (request.onSendCalled) {
      t.assert.fail('onSend hook called more than once')
      return
    }

    t.assert.ok('onSend hook called')
    request.onSendCalled = true

    if (resolveOnSendEntered) {
      resolveOnSendEntered()
      resolveOnSendEntered = null
    }

    // Introduce a delay (gives time for client-side abort to happen while the
    // request has already been processed, exercising the original issue).
    await new Promise(resolve => setTimeout(resolve, 50))
    return payload
  })

  // The handler must be async to trigger the error
  fastify.put('/', async (request, reply) => {
    t.assert.ok('PUT handler called')
    return reply.send({ hello: 'world' })
  })

  await fastify.listen({ port: 0 })

  const err = await runBadClientCall({
    hostname: 'localhost',
    port: fastify.server.address().port,
    path: '/',
    method: 'PUT'
  }, { test: 'me' }, onSendEntered)
  t.assert.equal(err.code, 'ECONNRESET')
})
```

