'use strict'

const tokenRegExp = /^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/
const invalidQuotedString = 'invalid quoted string'

/**
 * Parses a `Content-Type` header value into a media type and parameters.
 * A value without a valid `type/subtype` is reported as empty and invalid.
 */
class ContentType {
  #valid = false
  #empty = true
  #type = ''
  #subtype = ''
  #parameters = new Map()

  constructor (headerValue) {
    if (headerValue == null || headerValue === '' || headerValue === 'undefined') {
      return
    }
    if (typeof headerValue !== 'string') headerValue = String(headerValue)

    let sep = headerValue.indexOf(';')
    if (sep === -1) sep = headerValue.length
    const mediaType = trimOWS(headerValue.slice(0, sep))

    const slash = mediaType.indexOf('/')
    if (slash < 1) return
    const type = mediaType.slice(0, slash)
    const subtype = mediaType.slice(slash + 1)
    if (tokenRegExp.test(type) === false || tokenRegExp.test(subtype) === false) return

    this.#empty = false
    this.#valid = true
    this.#type = type.toLowerCase()
    this.#subtype = subtype.toLowerCase()

    if (sep < headerValue.length) {
      this.#parseParameters(headerValue, sep + 1)
    }
  }

  #parseParameters (str, pos) {
    const len = str.length
    while (pos < len) {
      // skip optional whitespace
      while (pos < len && (str[pos] === ' ' || str[pos] === '\t')) pos++
      const start = pos
      while (pos < len && str[pos] !== '=' && str[pos] !== ';') pos++
      const name = trimOWS(str.slice(start, pos)).toLowerCase()
      if (pos >= len || str[pos] === ';') {
        // parameter without a value: ignore it
        pos++
        continue
      }
      pos++ // skip '='
      let value
      if (str[pos] === '"') {
        pos++
        let result = ''
        let closed = false
        while (pos < len) {
          const ch = str[pos]
          if (ch === '\\' && pos + 1 < len) {
            result += str[pos + 1]
            pos += 2
            continue
          }
          if (ch === '"') {
            closed = true
            pos++
            break
          }
          result += ch
          pos++
        }
        value = closed ? result : invalidQuotedString
        // ignore anything up to the next separator
        while (pos < len && str[pos] !== ';') pos++
        pos++
      } else {
        const valueStart = pos
        while (pos < len && str[pos] !== ';') pos++
        value = trimOWS(str.slice(valueStart, pos))
        pos++
        if (tokenRegExp.test(value) === false) continue
      }
      if (tokenRegExp.test(name) && this.#parameters.has(name) === false) {
        this.#parameters.set(name, value)
      }
    }
  }

  get isEmpty () { return this.#empty }
  get isValid () { return this.#valid }
  get type () { return this.#type }
  get subtype () { return this.#subtype }
  get mediaType () { return this.#empty ? '' : `${this.#type}/${this.#subtype}` }
  get parameters () { return this.#parameters }

  toString () {
    if (this.#empty) return ''
    let result = this.mediaType
    for (const [name, value] of this.#parameters) {
      result += `; ${name}="${value.replace(/["\\]/g, '\\$&')}"`
    }
    return result
  }
}

function trimOWS (str) {
  let start = 0
  let end = str.length
  while (start < end && (str[start] === ' ' || str[start] === '\t')) start++
  while (end > start && (str[end - 1] === ' ' || str[end - 1] === '\t')) end--
  return str.slice(start, end)
}

module.exports = ContentType
