## t022: fix: chunk large HTTP/2 buffer replies

Chunk large non-stream HTTP/2 payload writes to avoid poisoning the session after cancellation.

User-provided streams remain unmodified; docs note apps should chunk large stream emissions.

Tests:
- node --test test/http2/plain.test.js
- node --test test/http2/*.test.js
- npm run lint
- npx markdownlint-cli2 docs/Reference/Reply.md --no-globs

You may update existing tests whose expectations your change intentionally alters.

Acceptance tests:

`test/http2/plain.pr6746.test.js`

```js
'use strict'

const { test } = require('node:test')
const http2 = require('node:http2')
const Fastify = require('../..')
const h2url = require('h2url')
const msg = { hello: 'world' }

test('http2 large non-stream replies are sent completely', async t => {
  const modes = ['buffer', 'string']

  for (const mode of modes) {
    await t.test(mode, async t => {
      const fastify = Fastify({ http2: true })
      const payload = mode === 'buffer'
        ? Buffer.alloc((64 * 1024) + 1, 'a')
        : 'a'.repeat((64 * 1024) + 1)
      const contentLength = Buffer.byteLength(payload)

      fastify.get('/large', async (req, reply) => {
        reply.header('content-type', 'application/octet-stream')
        reply.header('content-length', contentLength)

        return payload
      })

      await fastify.listen({ port: 0, host: '127.0.0.1' })

      const client = http2.connect(`http://127.0.0.1:${fastify.server.address().port}`)
      t.after(() => {
        client.close()
        return fastify.close()
      })

      await new Promise((resolve, reject) => {
        const large = client.request({
          [http2.constants.HTTP2_HEADER_METHOD]: http2.constants.HTTP2_METHOD_GET,
          [http2.constants.HTTP2_HEADER_PATH]: '/large'
        })
        const chunks = []

        large.on('error', reject)
        large.on('data', chunk => {
          chunks.push(chunk)
        })
        large.on('end', () => {
          t.assert.strictEqual(Buffer.concat(chunks).length, contentLength)
          resolve()
        })
        large.end()
      })
    })
  }
})

test('http2 large buffer replies can be cancelled without rejecting the next stream', async t => {
  const fastify = Fastify({ http2: true })
  const payload = Buffer.alloc(32 * 1024 * 1024, 'a')
  let smallHit = false

  fastify.get('/large', async (req, reply) => {
    reply.header('content-type', 'application/octet-stream')
    reply.header('content-length', payload.length)

    return payload
  })

  fastify.get('/small', async () => {
    smallHit = true
    return 'ok'
  })

  await fastify.listen({ port: 0, host: '127.0.0.1' })

  const client = http2.connect(`http://127.0.0.1:${fastify.server.address().port}`)
  t.after(() => {
    client.close()
    return fastify.close()
  })

  await new Promise((resolve, reject) => {
    let cancelTimer
    let requestTimer
    let timeout

    function cleanup () {
      clearTimeout(cancelTimer)
      clearTimeout(requestTimer)
      clearTimeout(timeout)
    }

    const large = client.request({
      [http2.constants.HTTP2_HEADER_METHOD]: http2.constants.HTTP2_METHOD_GET,
      [http2.constants.HTTP2_HEADER_PATH]: '/large'
    })
    let largeResponded = false

    large.on('error', err => {
      if (!largeResponded) {
        cleanup()
        reject(err)
      }
    })
    large.on('response', () => {
      largeResponded = true
      large.pause()
      cancelTimer = setTimeout(() => {
        large.close(http2.constants.NGHTTP2_CANCEL)
      }, 100)
      requestTimer = setTimeout(() => {
        const small = client.request({
          [http2.constants.HTTP2_HEADER_METHOD]: http2.constants.HTTP2_METHOD_GET,
          [http2.constants.HTTP2_HEADER_PATH]: '/small'
        })
        let body = ''

        timeout = setTimeout(() => {
          cleanup()
          reject(new Error('timed out waiting for /small response'))
        }, 3000)

        small.setEncoding('utf8')
        small.on('error', err => {
          cleanup()
          reject(err)
        })
        small.on('data', chunk => {
          body += chunk
        })
        small.on('end', () => {
          cleanup()
          t.assert.strictEqual(body, 'ok')
          t.assert.strictEqual(smallHit, true)
          resolve()
        })
        small.end()
      }, 200)
    })
    large.end()
  })
})
```

## t023: fix: clear socket._meta after response to prevent keep-alive leaks

## Summary

- **`socket._meta` held context/request/reply alive for the full lifetime of a keep-alive socket**; now cleared in `onResFinished` when the current request owns `_meta` (`socket._meta.request === request` check prevents a race where a concurrent request has already updated `_meta`)

## Files changed

| File | Change |
|---|---|
| `lib/reply.js` | In `onResFinished`: clears `socket._meta` when this request owns it |

## Test plan

- [x] Added test in `test/hooks.test.js` — registers an `onTimeout` hook (which triggers `_meta` to be set), then asserts `socket._meta === null` inside `onResponse`, which fires after the cleanup runs
- [x] Existing `test/handler-timeout.test.js` — 19/19 pass
- [x] Existing `test/hooks.test.js` — 92/92 pass (covers `onRequestAbort` and `onTimeout`)
- [x] Existing `test/keep-alive-timeout.test.js` — 2/2 pass
- [x] Existing `test/client-timeout.test.js` — pass

You may update existing tests whose expectations your change intentionally alters.

Acceptance tests:

`test/hooks.pr6799.test.js`

```js
'use strict'

const { test } = require('node:test')
const stream = require('node:stream')
const Fastify = require('..')
const fp = require('fastify-plugin')
const fs = require('node:fs')
const split = require('split2')
const symbols = require('../lib/symbols.js')
const payload = { hello: 'world' }
const proxyquire = require('proxyquire')
const { connect } = require('node:net')
const { sleep } = require('./helper')
const { waitForCb } = require('./toolkit.js')
const { fetch } = require('undici')

process.removeAllListeners('warning')

test('socket._meta is cleared after response to prevent keep-alive leaks', async t => {
  t.plan(3)
  const fastify = Fastify({ connectionTimeout: 500 })
  t.after(() => { fastify.close() })

  fastify.addHook('onTimeout', function (req, res, done) { done() })

  fastify.addHook('onResponse', function (req, reply, done) {
    t.assert.strictEqual(req.raw.socket._meta, null, 'socket._meta must be null after response')
    done()
  })

  fastify.get('/', async (req, reply) => {
    return { hello: 'world' }
  })

  const address = await fastify.listen({ port: 0 })
  const result = await fetch(address)
  t.assert.ok(result.ok)
  t.assert.strictEqual(result.status, 200)
})
